import type { GuidanceDocument } from '../types/guidance';
import type { RawUserContextSource } from './contracts';
import { readStoredUserContext } from './variantContext';

interface WorkItemContext {
  guidance?: GuidanceDocument[];
  context?: {
    contextBundlePath?: string;
    userContext?: RawUserContextSource[];
  };
}

export const workItemContextFiles = (
  input: WorkItemContext,
): { contextFiles: Array<{ path: string; label?: string }> } | undefined => {
  const paths = new Set<string>();
  const files = (input.context?.userContext ?? [])
    .filter(
      (
        source,
      ): source is Extract<RawUserContextSource, { transport: 'file' }> =>
        source.transport === 'file',
    )
    .filter((source) => {
      if (paths.has(source.path)) return false;
      paths.add(source.path);
      return true;
    })
    .map((source) => ({
      path: source.path,
      ...((source.label ?? source.originalFilename)
        ? { label: source.label ?? source.originalFilename }
        : {}),
    }));
  const guidanceFiles = (input.guidance ?? []).flatMap((document) => [
    ...(document.attachments ?? []).map((image) => ({
      path: image.path,
      label: `${document.title}: ${image.alt || image.source}`,
    })),
    ...(document.references ?? []).flatMap((reference) => {
      if (reference.kind === 'directory')
        return [
          { path: reference.path, label: `${document.title}: local directory` },
        ];
      return (reference.files ?? []).flatMap((file) =>
        file.path
          ? [{ path: file.path, label: `${document.title}: ${file.name}` }]
          : [],
      );
    }),
  ]);
  const hashes = new Set(
    (input.guidance ?? []).flatMap((document) =>
      (document.attachments ?? []).map((image) => image.hash),
    ),
  );
  const records =
    input.context?.contextBundlePath && hashes.size
      ? (readStoredUserContext(input.context.contextBundlePath) ?? [])
      : [];
  const repeatedPaths = new Set(
    records.flatMap(({ source, storage }) =>
      source.transport === 'file' &&
      storage?.sha256 &&
      hashes.has(storage.sha256)
        ? [source.path]
        : [],
    ),
  );
  const combined = [
    ...guidanceFiles,
    ...files.filter((file) => !repeatedPaths.has(file.path)),
  ].filter(
    (file, index, all) =>
      all.findIndex((candidate) => candidate.path === file.path) === index,
  );
  return combined.length > 0 ? { contextFiles: combined } : undefined;
};
